BEGIN;
CREATE TABLE IF NOT EXISTS radar_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_key text UNIQUE NOT NULL,run_date date NOT NULL,cutoff_at timestamptz NOT NULL,generated_at timestamptz NOT NULL,run_type text NOT NULL CHECK(run_type IN ('live','fixture')),market_context text NOT NULL,raw_report text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_live_run_per_day ON radar_runs(run_date) WHERE run_type='live';
CREATE TABLE IF NOT EXISTS radar_signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES radar_runs(id),ticker text NOT NULL,exchange text NOT NULL,market_symbol text NOT NULL,company text NOT NULL,sector text NOT NULL,tag text NOT NULL CHECK(tag IN ('RED','ORANGE','GREEN','DOUBLE_GREEN')),signal_price numeric CHECK(signal_price>0),currency text NOT NULL,catalyst_type text NOT NULL,data_status text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,ticker,exchange));
CREATE TABLE IF NOT EXISTS market_fetches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),symbol text NOT NULL,interval text NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL,payload jsonb NOT NULL,payload_hash text NOT NULL);
CREATE INDEX IF NOT EXISTS market_cache ON market_fetches(symbol,interval,fetched_at DESC);
CREATE TABLE IF NOT EXISTS price_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signal_id uuid NOT NULL REFERENCES radar_signals(id),session date NOT NULL,trading_days_since_signal int NOT NULL CHECK(trading_days_since_signal BETWEEN 1 AND 30),observed_at timestamptz NOT NULL,price numeric NOT NULL CHECK(price>0),performance_pct numeric NOT NULL,ohlc jsonb NOT NULL,fetch_id uuid NOT NULL REFERENCES market_fetches(id),split_audit_id uuid,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(signal_id,session),UNIQUE(signal_id,trading_days_since_signal));
CREATE TABLE IF NOT EXISTS signal_performance(signal_id uuid PRIMARY KEY REFERENCES radar_signals(id),metrics jsonb NOT NULL,calculated_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL,error text);
CREATE TABLE IF NOT EXISTS worker_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status text NOT NULL DEFAULT 'running',processed int NOT NULL DEFAULT 0,errors jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS split_audits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signal_id uuid NOT NULL REFERENCES radar_signals(id),event_hash text NOT NULL,factor numeric NOT NULL CHECK(factor>0),reason text NOT NULL,source text NOT NULL,approved_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(signal_id,event_hash));
CREATE TABLE IF NOT EXISTS data_conflicts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signal_id uuid NOT NULL REFERENCES radar_signals(id),session date NOT NULL,existing_hash text NOT NULL,new_hash text NOT NULL,fetch_id uuid NOT NULL REFERENCES market_fetches(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(signal_id,session,new_hash));
CREATE OR REPLACE FUNCTION reject_history_change() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'immutable history: % % forbidden',TG_TABLE_NAME,TG_OP;END;$$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['radar_runs','radar_signals','price_observations','market_fetches','split_audits','data_conflicts'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=t||'_immutable') THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_history_change()',t||'_immutable',t);EXECUTE format('CREATE TRIGGER %I BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION reject_history_change()',t||'_no_truncate',t);END IF;END LOOP;END;$$;
COMMIT;
